text = unicodedata.normalize("NFKD", title)
text = text.encode("ascii", "ignore").decode("ascii").lower()
text = text.replace("'", "")
slug = _NON_ALNUM.sub("-", text).strip("-")
if not slug:
    raise ValueError(f"cannot build a slug from {title!r}")
if len(slug) > max_length:
    words = slug.split("-")
    truncated = ""
    for word in words:
        candidate = f"{truncated}-{word}" if truncated else word
        if len(candidate) <= max_length:
            truncated = candidate
        else:
            break
    if not truncated:
        truncated = words[0][:max_length]
    slug = truncated
return slug
